"""
優先度付きキュー (Heap / Priority Queue) & 削除可能ヒープ & スライド最小値
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- MaxHeap: 最大値を取り出すヒープ (値を符号反転して管理)
- ErasableHeap: 任意の値の遅延削除をサポートするヒープ (O(log N))
  - push(x), erase(x), top(), pop()
- slide_min(a, k): 長さ n の数列 a に対し、各ウィンドウ (幅 k) の最小値を O(N) で計算 (両端キュー)
"""

import heapq
from collections import deque

# https://github.com/ddfkit/acsampl/blob/main/que.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class MaxHeap:
    def __init__(self,l=[]):self.h=[-x for x in l];heapq.heapify(self.h)
    def push(self,x):heapq.heappush(self.h,-x)
    def pop(self):return -heapq.heappop(self.h)
    def top(self):return -self.h[0]
    def __len__(self):return len(self.h)

# https://github.com/ddfkit/acsampl/blob/main/que.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class ErasableHeap:
    def __init__(self):self.p=[];self.q=[]
    def push(self,x):heapq.heappush(self.p,x)
    def erase(self,x):heapq.heappush(self.q,x)
    def _clean(self):
        while self.p and self.q and self.p[0]==self.q[0]:
            heapq.heappop(self.p);heapq.heappop(self.q)
    def top(self):self._clean();return self.p[0]
    def pop(self):self._clean();return heapq.heappop(self.p)
    def __len__(self):return len(self.p)-len(self.q)

# https://github.com/ddfkit/acsampl/blob/main/que.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def slide_min(a,k):
    q=deque();res=[]
    for i,v in enumerate(a):
        while q and a[q[-1]]>=v:q.pop()
        q.append(i)
        if i>=k-1:
            if q[0]<=i-k:q.popleft()
            res.append(a[q[0]])
    return res

if __name__ == "__main__":
    mh = MaxHeap([3, 1, 4])
    mh.push(5)
    assert mh.pop() == 5 and mh.pop() == 4

    eh = ErasableHeap()
    for x in [5, 2, 8, 3]: eh.push(x)
    assert eh.top() == 2
    eh.erase(2)
    assert eh.top() == 3

    assert slide_min([1, 3, -1, -3, 5, 3, 6, 7], 3) == [-1, -3, -3, -3, 3, 3]
    print("que.py: tests passed!")
